CREATE TABLE public.official_game_days(club_id text NOT NULL REFERENCES public.unrivaled_clubs(id),game_date date NOT NULL,PRIMARY KEY(club_id,game_date));
GRANT SELECT ON public.official_game_days TO anon,authenticated; GRANT ALL ON public.official_game_days TO service_role;
ALTER TABLE public.official_game_days ENABLE ROW LEVEL SECURITY; CREATE POLICY game_days_read ON public.official_game_days FOR SELECT USING(true);
CREATE TABLE public.schedule_checks(check_date date PRIMARY KEY,checked_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.schedule_checks TO authenticated; GRANT ALL ON public.schedule_checks TO service_role;
ALTER TABLE public.schedule_checks ENABLE ROW LEVEL SECURITY; CREATE POLICY checks_read ON public.schedule_checks FOR SELECT TO authenticated USING(true);
CREATE TABLE public.player_trades(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),league_id uuid NOT NULL REFERENCES public.leagues(id),from_team uuid NOT NULL REFERENCES public.teams(id),to_team uuid NOT NULL REFERENCES public.teams(id),offered_player uuid NOT NULL REFERENCES public.players(id),requested_player uuid NOT NULL REFERENCES public.players(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','denied','cancelled','countered','invalid')),parent_trade uuid REFERENCES public.player_trades(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.player_trades TO authenticated; GRANT ALL ON public.player_trades TO service_role;
ALTER TABLE public.player_trades ENABLE ROW LEVEL SECURITY; CREATE POLICY trade_read ON public.player_trades FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.teams t WHERE t.id IN(from_team,to_team) AND t.owner_id=auth.uid()));
CREATE TABLE public.player_waivers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),league_id uuid NOT NULL REFERENCES public.leagues(id),player_id uuid NOT NULL REFERENCES public.players(id),dropped_by uuid NOT NULL REFERENCES public.teams(id),expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours',resolved boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX one_open_waiver ON public.player_waivers(league_id,player_id) WHERE NOT resolved;
GRANT SELECT ON public.player_waivers TO authenticated; GRANT ALL ON public.player_waivers TO service_role;
ALTER TABLE public.player_waivers ENABLE ROW LEVEL SECURITY; CREATE POLICY waiver_read ON public.player_waivers FOR SELECT TO authenticated USING(public.league_member(league_id));
CREATE TABLE public.waiver_priority(league_id uuid NOT NULL REFERENCES public.leagues(id),team_id uuid PRIMARY KEY REFERENCES public.teams(id),rank bigint NOT NULL);
GRANT SELECT ON public.waiver_priority TO authenticated; GRANT ALL ON public.waiver_priority TO service_role;
ALTER TABLE public.waiver_priority ENABLE ROW LEVEL SECURITY; CREATE POLICY priority_read ON public.waiver_priority FOR SELECT TO authenticated USING(public.league_member(league_id));
CREATE TABLE public.waiver_claims(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),waiver_id uuid NOT NULL REFERENCES public.player_waivers(id),team_id uuid NOT NULL REFERENCES public.teams(id),drop_slot int NOT NULL CHECK(drop_slot BETWEEN 1 AND 6),drop_player uuid REFERENCES public.players(id),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','won','lost','cancelled','invalid')),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(waiver_id,team_id));
GRANT SELECT ON public.waiver_claims TO authenticated; GRANT ALL ON public.waiver_claims TO service_role;
ALTER TABLE public.waiver_claims ENABLE ROW LEVEL SECURITY; CREATE POLICY claim_read ON public.waiver_claims FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.teams t WHERE t.id=team_id AND t.owner_id=auth.uid()));
CREATE FUNCTION public.resolve_league_waivers(lid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w player_waivers;c waiver_claims;old_id uuid;pos text;won boolean; BEGIN IF auth.role()<>'service_role' AND NOT public.league_member(lid) THEN RAISE EXCEPTION 'Join this league first'; END IF; PERFORM 1 FROM leagues WHERE id=lid FOR UPDATE; INSERT INTO waiver_priority(league_id,team_id,rank) SELECT lid,t.id,row_number() OVER(ORDER BY t.draft_order DESC) FROM teams t WHERE t.league_id=lid ON CONFLICT(team_id) DO NOTHING; IF NOT (SELECT pickups_enabled FROM leagues WHERE id=lid) THEN RETURN; END IF; FOR w IN SELECT * FROM player_waivers WHERE league_id=lid AND NOT resolved AND expires_at<=now() ORDER BY expires_at,id FOR UPDATE LOOP won:=false; SELECT position INTO pos FROM players WHERE id=w.player_id; FOR c IN SELECT wc.* FROM waiver_claims wc JOIN waiver_priority wp ON wp.team_id=wc.team_id WHERE wc.waiver_id=w.id AND wc.status='pending' ORDER BY wp.rank,wc.created_at,wc.id LOOP SELECT player_id INTO old_id FROM roster_slots WHERE team_id=c.team_id AND slot=c.drop_slot; IF old_id IS DISTINCT FROM c.drop_player OR (c.drop_slot=1 AND pos<>'G') OR (c.drop_slot=2 AND pos<>'F') OR EXISTS(SELECT 1 FROM roster_slots WHERE league_id=lid AND player_id=w.player_id) THEN UPDATE waiver_claims SET status='invalid' WHERE id=c.id; CONTINUE; END IF; IF old_id IS NOT NULL THEN INSERT INTO player_waivers(league_id,player_id,dropped_by) VALUES(lid,old_id,c.team_id); END IF; UPDATE roster_slots SET player_id=w.player_id,projection=NULL WHERE team_id=c.team_id AND slot=c.drop_slot; UPDATE waiver_claims SET status='won' WHERE id=c.id; UPDATE waiver_priority SET rank=(SELECT max(rank)+1 FROM waiver_priority WHERE league_id=lid) WHERE team_id=c.team_id; INSERT INTO league_activity(league_id,message) SELECT lid,t.name||' won a waiver claim for '||p.name FROM teams t,players p WHERE t.id=c.team_id AND p.id=w.player_id; won:=true; EXIT; END LOOP; UPDATE waiver_claims SET status='lost' WHERE waiver_id=w.id AND status='pending'; UPDATE player_waivers SET resolved=true WHERE id=w.id; END LOOP; END $$;
CREATE OR REPLACE FUNCTION public.claim_player(tid uuid,pid uuid,drop_slot int DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lid uuid;s int;pos text;old_id uuid; BEGIN SELECT league_id INTO lid FROM teams WHERE id=tid AND owner_id=auth.uid(); IF lid IS NULL THEN RAISE EXCEPTION 'You can only manage your own team'; END IF; PERFORM 1 FROM leagues WHERE id=lid FOR UPDATE; IF (SELECT draft_status FROM leagues WHERE id=lid)<>'complete' THEN RAISE EXCEPTION 'Finish the draft before adding players'; END IF; IF NOT (SELECT pickups_enabled FROM leagues WHERE id=lid) THEN RAISE EXCEPTION 'Player pickups are paused by the commissioner'; END IF; PERFORM public.resolve_league_waivers(lid); IF EXISTS(SELECT 1 FROM roster_slots WHERE league_id=lid AND player_id=pid) THEN RAISE EXCEPTION 'Player is already rostered'; END IF; IF EXISTS(SELECT 1 FROM player_waivers WHERE league_id=lid AND player_id=pid AND NOT resolved) THEN RAISE EXCEPTION 'Player is on waivers; submit a waiver claim'; END IF; SELECT position INTO pos FROM players WHERE id=pid; IF pos IS NULL THEN RAISE EXCEPTION 'Player not found'; END IF; s:=drop_slot; IF s IS NULL THEN SELECT slot INTO s FROM roster_slots WHERE team_id=tid AND player_id IS NULL ORDER BY CASE WHEN slot>=4 THEN 0 ELSE 1 END,slot LIMIT 1; END IF; IF s IS NULL OR s NOT BETWEEN 1 AND 6 THEN RAISE EXCEPTION 'Choose a player to drop'; END IF; IF (s=1 AND pos<>'G') OR (s=2 AND pos<>'F') THEN RAISE EXCEPTION 'Choose a matching position or bench slot'; END IF; SELECT player_id INTO old_id FROM roster_slots WHERE team_id=tid AND slot=s; IF old_id IS NOT NULL THEN INSERT INTO player_waivers(league_id,player_id,dropped_by) VALUES(lid,old_id,tid); END IF; UPDATE roster_slots SET player_id=pid,projection=NULL WHERE team_id=tid AND slot=s; INSERT INTO league_activity(league_id,message) SELECT lid,'Added '||name FROM players WHERE id=pid; END $$;
CREATE FUNCTION public.submit_waiver_claim(wid uuid,tid uuid,slot_no int) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w player_waivers;p text;old_id uuid; BEGIN SELECT * INTO w FROM player_waivers WHERE id=wid; IF w.id IS NULL OR NOT EXISTS(SELECT 1 FROM teams WHERE id=tid AND league_id=w.league_id AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'Invalid waiver claim'; END IF; PERFORM 1 FROM leagues WHERE id=w.league_id FOR UPDATE; SELECT * INTO w FROM player_waivers WHERE id=wid; IF w.resolved OR w.expires_at<=now() THEN RAISE EXCEPTION 'The waiver window has closed'; END IF; IF w.dropped_by=tid THEN RAISE EXCEPTION 'The dropping team must wait until waivers clear'; END IF; IF NOT (SELECT pickups_enabled FROM leagues WHERE id=w.league_id) THEN RAISE EXCEPTION 'Player pickups are paused'; END IF; SELECT position INTO p FROM players WHERE id=w.player_id; IF slot_no NOT BETWEEN 1 AND 6 OR (slot_no=1 AND p<>'G') OR (slot_no=2 AND p<>'F') THEN RAISE EXCEPTION 'Choose an eligible roster slot'; END IF; SELECT player_id INTO old_id FROM roster_slots WHERE team_id=tid AND slot=slot_no; INSERT INTO waiver_claims(waiver_id,team_id,drop_slot,drop_player) VALUES(wid,tid,slot_no,old_id) ON CONFLICT(waiver_id,team_id) DO UPDATE SET drop_slot=excluded.drop_slot,drop_player=excluded.drop_player,status='pending'; END $$;
CREATE FUNCTION public.cancel_waiver_claim(cid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE waiver_claims wc SET status='cancelled' WHERE wc.id=cid AND wc.status='pending' AND EXISTS(SELECT 1 FROM teams t WHERE t.id=wc.team_id AND t.owner_id=auth.uid()); IF NOT FOUND THEN RAISE EXCEPTION 'Claim not found'; END IF; END $$;
CREATE FUNCTION public.check_trade_players(lid uuid,from_id uuid,to_id uuid,give_id uuid,get_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE a roster_slots;b roster_slots;ap text;bp text;today date; BEGIN today:=(now() AT TIME ZONE 'America/New_York')::date; IF (SELECT draft_status FROM leagues WHERE id=lid)<>'complete' OR (SELECT is_demo FROM leagues WHERE id=lid) THEN RAISE EXCEPTION 'Trades open after your league draft'; END IF; IF from_id=to_id OR NOT EXISTS(SELECT 1 FROM teams WHERE id=to_id AND league_id=lid AND owner_id IS NOT NULL) THEN RAISE EXCEPTION 'Choose another manager-owned team'; END IF; IF NOT EXISTS(SELECT 1 FROM schedule_checks WHERE check_date=today AND checked_at>now()-interval '15 minutes') THEN RAISE EXCEPTION 'Refresh the official game schedule before trading'; END IF; IF EXISTS(SELECT 1 FROM players p JOIN official_game_days g ON g.club_id=p.club_id WHERE p.id IN(give_id,get_id) AND g.game_date=today) THEN RAISE EXCEPTION 'Players whose club plays today cannot be traded'; END IF; SELECT * INTO a FROM roster_slots WHERE team_id=from_id AND league_id=lid AND player_id=give_id; SELECT * INTO b FROM roster_slots WHERE team_id=to_id AND league_id=lid AND player_id=get_id; IF a.id IS NULL OR b.id IS NULL THEN RAISE EXCEPTION 'These players are no longer on the offered rosters'; END IF; SELECT position INTO ap FROM players WHERE id=give_id; SELECT position INTO bp FROM players WHERE id=get_id; IF (a.slot=1 AND bp<>'G') OR (a.slot=2 AND bp<>'F') OR (b.slot=1 AND ap<>'G') OR (b.slot=2 AND ap<>'F') THEN RAISE EXCEPTION 'Trade must preserve eligible Guard and Forward slots'; END IF; END $$;
CREATE FUNCTION public.offer_player_trade(from_id uuid,to_id uuid,give_id uuid,get_id uuid,parent_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE lid uuid;new_id uuid;parent player_trades; BEGIN SELECT league_id INTO lid FROM teams WHERE id=from_id AND owner_id=auth.uid(); IF lid IS NULL THEN RAISE EXCEPTION 'You can only offer your own players'; END IF; PERFORM 1 FROM leagues WHERE id=lid FOR UPDATE; PERFORM public.check_trade_players(lid,from_id,to_id,give_id,get_id); IF parent_id IS NOT NULL THEN SELECT * INTO parent FROM player_trades WHERE id=parent_id FOR UPDATE; IF parent.status<>'pending' OR parent.to_team<>from_id OR parent.from_team<>to_id OR parent.league_id<>lid THEN RAISE EXCEPTION 'Invalid counteroffer'; END IF; UPDATE player_trades SET status='countered',updated_at=now() WHERE id=parent_id; END IF; INSERT INTO player_trades(league_id,from_team,to_team,offered_player,requested_player,parent_trade) VALUES(lid,from_id,to_id,give_id,get_id,parent_id) RETURNING id INTO new_id; RETURN new_id; END $$;
CREATE FUNCTION public.respond_player_trade(trade_id uuid,decision text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tr player_trades;a uuid;b uuid; BEGIN SELECT * INTO tr FROM player_trades WHERE id=trade_id; IF tr.id IS NULL THEN RAISE EXCEPTION 'Trade not found'; END IF; PERFORM 1 FROM leagues WHERE id=tr.league_id FOR UPDATE; SELECT * INTO tr FROM player_trades WHERE id=trade_id FOR UPDATE; IF tr.status<>'pending' THEN RAISE EXCEPTION 'This trade is no longer pending'; END IF; IF decision='cancel' THEN IF NOT EXISTS(SELECT 1 FROM teams WHERE id=tr.from_team AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'Only the sender can cancel'; END IF; UPDATE player_trades SET status='cancelled',updated_at=now() WHERE id=trade_id; RETURN; END IF; IF NOT EXISTS(SELECT 1 FROM teams WHERE id=tr.to_team AND owner_id=auth.uid()) THEN RAISE EXCEPTION 'Only the recipient can respond'; END IF; IF decision='deny' THEN UPDATE player_trades SET status='denied',updated_at=now() WHERE id=trade_id; RETURN; END IF; IF decision<>'accept' THEN RAISE EXCEPTION 'Invalid response'; END IF; PERFORM public.check_trade_players(tr.league_id,tr.from_team,tr.to_team,tr.offered_player,tr.requested_player); SELECT id INTO a FROM roster_slots WHERE team_id=tr.from_team AND player_id=tr.offered_player; SELECT id INTO b FROM roster_slots WHERE team_id=tr.to_team AND player_id=tr.requested_player; UPDATE roster_slots SET player_id=NULL,projection=NULL WHERE id IN(a,b); UPDATE roster_slots SET player_id=tr.requested_player WHERE id=a; UPDATE roster_slots SET player_id=tr.offered_player WHERE id=b; UPDATE player_trades SET status='accepted',updated_at=now() WHERE id=trade_id; UPDATE player_trades SET status='invalid',updated_at=now() WHERE league_id=tr.league_id AND status='pending' AND (offered_player IN(tr.offered_player,tr.requested_player) OR requested_player IN(tr.offered_player,tr.requested_player)); INSERT INTO league_activity(league_id,message) VALUES(tr.league_id,'Player trade accepted'); END $$;
REVOKE ALL ON FUNCTION public.resolve_league_waivers(uuid),public.submit_waiver_claim(uuid,uuid,int),public.cancel_waiver_claim(uuid),public.check_trade_players(uuid,uuid,uuid,uuid,uuid),public.offer_player_trade(uuid,uuid,uuid,uuid,uuid),public.respond_player_trade(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.resolve_league_waivers(uuid) TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION public.submit_waiver_claim(uuid,uuid,int),public.cancel_waiver_claim(uuid),public.offer_player_trade(uuid,uuid,uuid,uuid,uuid),public.respond_player_trade(uuid,text) TO authenticated;